//! Parity tests against fixtures generated by
//! `parity/gen_fixtures.py` from Python inflect 7.6.0. Regenerate them with
//! `pixi run --manifest-path crates/ports/inflect/pixi.toml fixtures`.

use inflect::{NumberOrWord, NumberToWordsOptions, engine};
use serde::Deserialize;

const CASES: &str = include_str!("fixtures/cases.jsonl");
const RANGE: &str = include_str!("fixtures/range.json");

/// Python keyword arguments of one block of cases.
#[derive(Debug, Deserialize, Default)]
struct Kw {
  group: Option<i64>,
  comma: Option<String>,
  andword: Option<String>,
  zero: Option<String>,
  one: Option<String>,
  /// `None` when absent, `Some(None)` for Python `None`.
  #[serde(default, deserialize_with = "nullable")]
  decimal: Option<Option<String>>,
}

fn nullable<'de, D: serde::Deserializer<'de>>(d: D) -> Result<Option<Option<String>>, D::Error> {
  Option::<String>::deserialize(d).map(Some)
}

#[derive(Deserialize)]
#[serde(untagged)]
enum Outcome {
  Ok(String),
  Err { e: String },
}

#[derive(Deserialize)]
struct Block {
  f: String,
  #[serde(default)]
  kw: Kw,
  c: Vec<(String, String, Outcome)>,
}

#[derive(Deserialize)]
struct Range {
  start: i64,
  end: i64,
  default: Vec<String>,
  andword_empty: Vec<String>,
}

fn options(kw: &Kw) -> NumberToWordsOptions<'_> {
  let d = NumberToWordsOptions::default();
  NumberToWordsOptions {
    group: kw.group.unwrap_or(d.group),
    comma: kw.comma.as_deref().unwrap_or(d.comma),
    andword: kw.andword.as_deref().unwrap_or(d.andword),
    zero: kw.zero.as_deref().unwrap_or(d.zero),
    one: kw.one.as_deref().unwrap_or(d.one),
    decimal: match &kw.decimal {
      None => d.decimal,
      Some(v) => v.as_deref(),
    },
  }
}

fn expected(outcome: &Outcome) -> Result<String, String> {
  match outcome {
    Outcome::Ok(s) => Ok(s.clone()),
    Outcome::Err { e } => Err(e.clone()),
  }
}

#[test]
fn cases_jsonl() {
  let mut p = engine::new();
  let mut total = 0usize;
  let mut mismatches = Vec::new();
  for line in CASES.lines() {
    let block: Block = serde_json::from_str(line).expect("bad fixture line");
    let opts = options(&block.kw);
    for (t, n, outcome) in &block.c {
      let num = match t.as_str() {
        "i" => NumberOrWord::Number(n.parse().expect("int fixture out of i128 range")),
        "s" => NumberOrWord::Word(n),
        other => panic!("unknown input type {other}"),
      };
      let got = match block.f.as_str() {
        "number_to_words" => p.number_to_words(num, &opts),
        "ordinal" => p.ordinal(num),
        other => panic!("unknown function {other}"),
      }
      .map_err(|e| e.name().to_string());
      total += 1;
      let want = expected(outcome);
      if got != want {
        mismatches.push(format!(
          "{}({t}:{n:?}, {:?}): got {got:?}, want {want:?}",
          block.f, block.kw
        ));
      }
    }
  }
  assert!(total > 15000, "too few cases: {total}");
  assert!(
    mismatches.is_empty(),
    "{} of {total} cases differ:\n{}",
    mismatches.len(),
    mismatches
      .iter()
      .take(50)
      .cloned()
      .collect::<Vec<_>>()
      .join("\n")
  );
}

#[test]
fn range_0_to_20000() {
  let range: Range = serde_json::from_str(RANGE).expect("bad range.json");
  assert_eq!(range.default.len() as i64, range.end - range.start + 1);
  assert_eq!(range.andword_empty.len(), range.default.len());
  let mut p = engine::new();
  let default = NumberToWordsOptions::default();
  let no_and = NumberToWordsOptions {
    andword: "",
    ..Default::default()
  };
  for (i, (want_default, want_no_and)) in range.default.iter().zip(&range.andword_empty).enumerate()
  {
    let n = range.start + i as i64;
    assert_eq!(
      &p.number_to_words(n, &default).unwrap(),
      want_default,
      "number_to_words({n})"
    );
    assert_eq!(
      &p.number_to_words(n, &no_and).unwrap(),
      want_no_and,
      "number_to_words({n}, andword='')"
    );
  }
}
